<style>
:root{--app-bg:#f4f7fb;--surface:#fff;--surface-soft:#f8fafc;--ink:#172033;--muted:#667085;--line:#e4e7ec;--primary:#2563eb;--primary-dark:#1d4ed8;--nav:#111827;--success:#15803d;--danger:#dc2626;--warning:#b45309;--shadow:0 12px 34px rgba(15,23,42,.07)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{min-height:100vh;margin:0;background:radial-gradient(circle at 90% 0,#e8efff 0,transparent 26%),var(--app-bg);color:var(--ink);font:15px/1.55 'Noto Sans',ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{width:min(1320px,calc(100% - 48px));margin:0 auto;padding:28px 0 56px}h1,h2,h3{color:#101828;letter-spacing:-.035em}h1{font-size:clamp(32px,4vw,48px);line-height:1.08;margin:34px 0 12px}h2{font-size:24px}a{color:inherit}header,.card-head,.section-head{display:flex;justify-content:space-between;align-items:center;gap:18px}header{margin-bottom:30px;padding:18px 20px;border:1px solid var(--line);border-radius:18px;background:rgba(255,255,255,.88);box-shadow:var(--shadow);backdrop-filter:blur(12px)}.brand{margin-top:2px;font-size:22px;font-weight:800;letter-spacing:-.04em}.button{display:inline-flex;min-height:44px;align-items:center;justify-content:center;padding:11px 17px;border:1px solid transparent;border-radius:11px;background:var(--primary);color:#fff;font-family:inherit;font-size:14px;font-weight:700;line-height:1.2;cursor:pointer;text-decoration:none;box-shadow:0 5px 14px rgba(37,99,235,.18);transition:transform .18s ease,background .18s ease,box-shadow .18s ease}.button:hover{background:var(--primary-dark);box-shadow:0 8px 20px rgba(37,99,235,.25);transform:translateY(-1px)}.button.secondary{background:var(--nav);box-shadow:0 5px 14px rgba(17,24,39,.15)}.button.whatsapp{background:#16a34a;box-shadow:0 5px 14px rgba(22,163,74,.18)}.button.full{width:100%}.actions,.row-actions{display:flex;gap:10px;align-items:center}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px}.admin-columns{display:grid;grid-template-columns:minmax(300px,.8fr) minmax(420px,1.2fr);gap:24px}.card{padding:24px;border:1px solid var(--line);border-radius:18px;background:var(--surface);box-shadow:var(--shadow)}.restaurant-card{margin-bottom:14px}.restaurant-card h3{margin:0 0 7px;font-size:20px}.muted,small{color:var(--muted)}.error{margin:12px 0;padding:12px 15px;border:1px solid #fecaca;border-radius:11px;background:#fef2f2;color:#b42318}.success{margin:14px 0;padding:13px 16px;border:1px solid #bbf7d0;border-radius:11px;background:#f0fdf4;color:#166534}.form-stack{display:grid;gap:14px}.form-stack label{font-size:13px;font-weight:650}.form-stack input,.form-stack select,.form-stack textarea{display:block;width:100%;min-height:46px;margin-top:6px;padding:11px 13px;border:1px solid #d0d5dd;border-radius:10px;background:#fff;color:var(--ink);outline:0;transition:border-color .18s ease,box-shadow .18s ease}.form-stack textarea{min-height:100px;resize:vertical}.form-stack input:focus,.form-stack select:focus,.form-stack textarea:focus{border-color:#84adff;box-shadow:0 0 0 4px rgba(37,99,235,.11)}.form-stack small{display:block;margin-top:5px;font-weight:400}.check{display:flex!important;align-items:center;gap:9px}.check input{display:inline-block;width:18px;min-height:18px;margin:0;accent-color:var(--primary)}.edit-restaurant-form{padding-top:16px}.text-link,.booking-name,.row-actions a{color:var(--primary);font-weight:700;text-decoration:none}.text-link:hover,.booking-name:hover,.row-actions a:hover{text-decoration:underline}.whatsapp-link{color:#15803d;font-weight:700;text-decoration:none}.status{display:inline-flex;align-items:center;padding:6px 10px;border-radius:999px;background:#f2f4f7;color:#475467;font-size:12px;font-weight:750;white-space:nowrap}.status-pending,.status-review{background:#fff7ed;color:#b45309}.status-confirmed,.status-active,.status-paid{background:#ecfdf3;color:#067647}.status-cancelled,.status-inactive,.status-rejected{background:#fef3f2;color:#b42318}.table-scroll{overflow:auto;border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:var(--shadow)}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:14px 16px;border-bottom:1px solid #eef1f5;text-align:left;vertical-align:top}th{background:#f8fafc;color:#667085;font-size:11px;font-weight:750;letter-spacing:.045em;text-transform:uppercase}tbody tr{transition:background .15s ease}tbody tr:hover{background:#f8fbff}tbody tr:last-child td{border-bottom:0}.section-head{margin-top:34px}.section-head h2{margin-bottom:4px}.booking-detail-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,.7fr);gap:22px;margin-top:24px}.booking-main-card h1{margin-top:0}.eyebrow{margin:0 0 8px;color:var(--primary);font-size:10px;letter-spacing:1.6px;font-weight:800}.detail-list{margin:25px 0 0}.detail-list div{display:grid;grid-template-columns:190px 1fr;gap:15px;padding:13px 0;border-bottom:1px solid #eef1f5}.detail-list dt{color:var(--muted)}.detail-list dd{margin:0}details{margin-top:16px;padding-top:12px;border-top:1px solid var(--line)}summary{cursor:pointer;font-weight:700}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid rgba(37,99,235,.25);outline-offset:3px}
@media(max-width:760px){body{background:var(--app-bg)}.admin-columns,.booking-detail-grid{grid-template-columns:1fr}.shell{width:calc(100% - 28px);padding-top:14px}header,.card-head{align-items:flex-start;flex-direction:column}.actions{flex-wrap:wrap}.actions .button{flex:1}.card{padding:18px;border-radius:15px}.detail-list div{grid-template-columns:1fr;gap:3px}th,td{padding:11px 12px}.table-scroll{border-radius:14px}}
</style>
